export const Schema = z
    .object({
    抽卡进度: z.coerce.number().prefault(0),
    可用抽数: z.coerce.number().transform(v => Math.max(0, v)).prefault(1),
    剩余分钟: z.coerce.number().transform(v => Math.max(0, v)).prefault(0),
})
    .transform(data => {
    while (data.抽卡进度 >= 100) {
        data.抽卡进度 -= 100;
        data.可用抽数 += 1;
    }
    data.抽卡进度 = _.clamp(data.抽卡进度, 0, 99);
    return data;
});
